SELECT id FROM hr_leave_type WHERE tenant_id = #{tenantId} AND encashment_flag = 1
UNION SELECT leave_type_id FROM hr_leave_ledger WHERE tenant_id = #{tenantId} AND employee_id = #{employeeId}
ORDER BY 1

mapper.update:
UPDATE hr_salary_slip SET reserved_settlement_id = #{settlementId}, version = version + 1
WHERE tenant_id = #{tenantId} AND employee_id = #{employeeId} AND id = #{sourceId} AND deleted = 0
  AND reserved_settlement_id IS NULL AND status IN ('SUBMITTED','CONFIRMED') AND version = #{version}

UPDATE hr_training_recovery SET settlement_id = #{settlementId}, version = version + 1
WHERE tenant_id = #{tenantId} AND employee_id = #{employeeId} AND recovery_id = #{sourceId}
  AND settlement_id IS NULL AND status = 'CONFIRMED' AND version = #{version}

UPDATE hr_training_recovery SET settlement_id = NULL, version = version + 1
WHERE tenant_id = #{tenantId} AND employee_id = #{employeeId} AND recovery_id = #{sourceId}
  AND settlement_id = #{settlementId} AND status = 'CONFIRMED'
